function reddUp%% closes screens, shuts down eyelink, clears working memory% % by Martin Rolfsglobal const% re-enable keyboardListenChar(1);if ~const.TEST    % close eyelink data file    Eyelink('closefile');    WaitSecs(2.0); % Zeit fur Tracker, alles fertigzubekommen        % download data file    if const.TEST<1        fprintf(1,'Receiving data file\n');        status=Eyelink('ReceiveFile');        if status == 0            fprintf(1,'\n\nFile transfer successful\n\n');        elseif status < 0            fprintf(1,'\n\nError occurred during file transfer\n\n');        else            fprintf(1,'\n\nFile has been transferred (%i Bytes)\n\n',status);        end    end        %Eyelink runterfahren    Eyelink('shutdown');    WaitSecs(2.0);end% Disable driver, plot some timing plots:PsychProPixx('DisableFastDisplayMode', 1);% reset datapixxDatapixx('SetPropixxDlpSequenceProgram',0);Datapixx('RegWr');Datapixx('Close');% Screens schliessenShowCursor;% Speicher aufraumenclear mex;clear fun;home;